---@class MonsterBossRewardConfig
local MonsterBossRewardConfig = T(Global, "MonsterBossRewardConfig")
---@type table
local ConfigList = {}

---@private
function MonsterBossRewardConfig:init()
    local config = FileUtil.getGameConfigFromCsv("monster/MonsterBossReward.csv")
    for _, item in pairs(config or {}) do
        local monsterId = tonumber(item.monsterId)
        local monster = ConfigList[monsterId] or {}
        local rank = tonumber(item.rank)
        local rewards = monster[rank] or {}
        table.insert(rewards, {
            tonumber(item.rewardId),
            tonumber(item.rewardCount),
            tonumber(item.weight) or 10000,
            item.tip or "#"
        })
        monster[rank] = rewards
        ConfigList[monsterId] = monster
    end
end

function MonsterBossRewardConfig:getAllCfgs()
    return ConfigList
end

function MonsterBossRewardConfig:hasBossReward(monsterId)
    return ConfigList[monsterId] ~= nil
end

function MonsterBossRewardConfig:getRewards(monsterId, rank)
    local monster = ConfigList[monsterId]
    if not monster then
        return {}
    end
    local ranks = {}
    for r, _ in pairs(monster) do
        table.insert(ranks, r)
    end
    table.sort(ranks, function(a, b)
        return a < b
    end)
    for _, r in pairs(ranks) do
        if rank <= r then
            return monster[r]
        end
    end
    return {}
end

MonsterBossRewardConfig:init()

return MonsterBossRewardConfig